class ExhumaCardSwipeStackElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-card-swipe-stack');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-card-swipe-stack')) {
  customElements.define('exhuma-card-swipe-stack', ExhumaCardSwipeStackElement);
}

